#[derive(Debug)]
pub struct NoteDto { pub id: i64, pub body: String }

fn find_note(conn: &rusqlite::Connection, id: i64) -> rusqlite::Result<Option<NoteDto>> {
    conn.query_row(
        "SELECT id, body FROM notes WHERE id = ?1",
        [id],
        |r| Ok(NoteDto { id: r.get(0)?, body: r.get(1)? }),
    )
    .optional()
}

fn main() {
    let conn = rusqlite::Connection::open_in_memory().expect("db");
    conn.execute_batch("CREATE TABLE notes(id INTEGER PRIMARY KEY, body TEXT);")
        .and_then(|_| conn.execute("INSERT INTO notes(body) VALUES ('hi')", []))
        .expect("seed");
    println!("{:?}", find_note(&conn, 1));
    println!("{:?}", find_note(&conn, 99));
}

