use std::collections::HashMap;

#[derive(Default)]
struct Repo {
    inner: HashMap<i64, String>,
    next: i64,
}

impl Repo {
    fn insert(&mut self, body: &str) -> bool {
        self.next += 1;
        self.inner.insert(self.next, body.to_string()).is_none()
    }
    fn upsert(&mut self, id: i64, body: &str) -> bool {
        self.inner.insert(id, body.to_string()).is_none()
    }
    fn get(&self, id: i64) -> Option<String> {
        self.inner.get(&id).cloned()
    }
}

fn main() {
    let mut repo = Repo::default();
    println!("{}", repo.insert("alpha"));
    println!("{}", repo.upsert(1, "alpha v2"));
    println!("{:?}", repo.get(1));
    println!("{:?}", repo.get(42));
}
